var userEvents = new List<(string UserId, string EventType, DateTime Timestamp)>
{
    ("u1", "login", DateTime.Parse("2024-01-01T08:00:00Z")),
    ("u2", "login", DateTime.Parse("2024-01-01T08:05:00Z")),
    ("u1", "logout", DateTime.Parse("2024-01-01T09:00:00Z")),
    ("u1", "login", DateTime.Parse("2024-01-01T10:00:00Z"))
};

// Stream: every event is retained
foreach (var evt in userEvents)
    Console.WriteLine($"{evt.Timestamp:u} {evt.UserId} -> {evt.EventType}");

// Table: latest state per user (fold by key)
var latestState = userEvents
    .GroupBy(e => e.UserId)
    .ToDictionary(g => g.Key, g => g.OrderByDescending(e => e.Timestamp).First());

foreach (var (userId, state) in latestState)
    Console.WriteLine($"{userId}: {state.EventType} at {state.Timestamp:u}");
